# try / except：抓錯不讓程式 crash

# === 基本 try / except ===
def safe_divide(a, b):
    try:
        result = a / b
        return f"答案是 {result}"
    except ZeroDivisionError:
        return "❌ 不能除以 0"
    except TypeError:
        return "❌ 型別錯誤"

print(safe_divide(10, 2))
print(safe_divide(10, 0))      # 觸發 ZeroDivisionError
print(safe_divide(10, "abc"))  # 觸發 TypeError

# === try / except / else / finally ===
def read_data(value):
    try:
        num = int(value)
    except ValueError as e:
        print(f"❌ 解析失敗：{e}")
    else:
        print(f"✓ 解析成功：{num}")
    finally:
        print(f"--- 處理 '{value}' 結束 ---\n")

read_data("123")
read_data("abc")

# === 自訂 Exception ===
class AgeError(Exception):
    pass

def check_age(age):
    if age < 0:
        raise AgeError(f"年齡不能負數: {age}")
    if age > 150:
        raise AgeError(f"年齡太大: {age}")
    return age

try:
    check_age(-5)
except AgeError as e:
    print(f"自訂錯誤：{e}")
